def components(grid,wall):
 h,w=grid.shape; seen=set(); res=[]
 for r in range(h):
  for c in range(w):
   if grid[r,c]==wall or (r,c) in seen: continue
   seen.add((r,c)); q=[(r,c)]; cells=[]
   for p in q:
    cells.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     nr,nc=p[0]+dr,p[1]+dc
     if 0<=nr<h and 0<=nc<w and grid[nr,nc]!=wall and (nr,nc) not in seen:
      seen.add((nr,nc));q.append((nr,nc))
   res.append(cells)
 return res
