def fill_cheb_depth(A,B,wall,bg,boundary8=False):
 h,w=A.shape;P=A.copy();meta=[]
 for i,cells in enumerate(components(A,wall)):
  csset=set(cells);rs=[r for r,c in cells];cols=[c for r,c in cells];r0,r1=min(rs),max(rs);c0,c1=min(cols),max(cols)
  specs=[(r,c,int(A[r,c])) for r,c in cells if A[r,c] not in (bg,wall)]
  if not specs:continue
  corners={'tl':(r0,c0),'tr':(r0,c1),'bl':(r1,c0),'br':(r1,c1)}
  name,corner=min(corners.items(),key=lambda kv:sum(abs(r-kv[1][0])+abs(c-kv[1][1]) for r,c,v in specs))
  dr=1 if name.startswith('t') else -1;dc=1 if name.endswith('l') else -1
  seq=[];got=False;rr,cc=corner
  while r0<=rr<=r1 and c0<=cc<=c1:
   v=int(A[rr,cc])
   if v==bg:
    if got:break
    seq.append(v)
   elif v==wall:break
   else:seq.append(v);got=True
   rr+=dr;cc+=dc
  if not got:continue
  dist={};q=deque()
  offsets=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
  bdoffs=offsets if boundary8 else ((1,0),(-1,0),(0,1),(0,-1))
  for r,c in cells:
   isbd=False
   for dr0,dc0 in bdoffs:
    nr,nc=r+dr0,c+dc0
    if not (0<=nr<h and 0<=nc<w) or (nr,nc) not in csset:
     isbd=True;break
   if isbd:dist[r,c]=0;q.append((r,c))
  while q:
   r,c=q.popleft()
   for dr0,dc0 in offsets:
    p=r+dr0,c+dc0
    if p in csset and p not in dist:dist[p]=dist[r,c]+1;q.append(p)
  for r,c in cells:P[r,c]=seq[dist[r,c]%len(seq)]
  meta.append((i,name,seq,max(dist.values())))
 return P,meta
